window.BASECAMP = {"version": 2, "release": "wip", "reviewDate": "2026-09-18", "title": "mad money · basecamp", "types": {"presentations": {"label": "presentation studies", "definition": "formats for reading, arranging and comparing case material."}, "concepts": {"label": "game concepts", "definition": "proposals for the player’s activity, objectives and progression."}, "playables": {"label": "playable scenarios", "definition": "implemented situations with fixed rules, resources and outcomes."}, "tools": {"label": "design tools", "definition": "applications for composing scenes, editing relationships and testing rules."}, "agency": {"label": "agency models", "definition": "limits on what the player knows, controls and can change."}}, "implementationStates": {"outlined": "central activity identified; detailed rules remain open.", "specified": "rules or structure described; a complete runtime is not available.", "implemented": "an interactive artifact exists; its scope is stated separately."}, "entries": [{"id": "e01", "title": "forensic explainer", "verb": "read / trace / compare", "loop": ["chapter", "diagram", "source"], "sources": ["s16"], "type": "presentations", "implementation": "implemented", "lead": "a chaptered case account organized as diagrams, tables and records.", "question": "can readers trace an explanation to its supporting records?", "limit": "presentation only; no management economy or player-controlled outcome.", "scope": "chapter navigation and evidence diagrams", "availability": "archived presentation", "revision": "presentation study · 2026-06", "links": [{"label": "archived plan", "url": "sources/s16.html"}], "media": [{"poster": "previews/e01.svg", "kind": "concept diagram", "caption": "chaptered evidence presentation · schematic"}], "image": "previews/e01.svg"}, {"id": "e02", "title": "specimen world + component bench", "verb": "arrange / inspect / calculate", "loop": ["artifact", "interaction", "inspection"], "sources": ["s17"], "type": "presentations", "implementation": "implemented", "lead": "case material arranged as draggable paper, terminals and interactive specimens, with a separate component inspector.", "question": "which document interactions make dense information easier to examine?", "limit": "visual interactions and calculations; no production schedule or management economy.", "scope": "paper, terminal and component interactions", "availability": "reference only", "revision": "material study · 2026-06", "links": [], "media": [{"poster": "previews/e02.svg", "kind": "concept diagram", "caption": "paper, terminal and component formats · schematic"}], "image": "previews/e02.svg"}, {"id": "e03", "title": "agency as a park", "verb": "place / manage / inspect", "loop": ["place", "watch", "adjust"], "sources": ["s21", "s02"], "type": "concepts", "implementation": "outlined", "lead": "an agency represented as a park: departments, client and supplier visitors, sites and placeable work.", "question": "which objects require placement, and which belong in a record view?", "limit": "the placement model must distinguish projects, sites and legal entities.", "scope": "spatial management concept", "availability": "design outline", "revision": "concept · 2026-09", "links": [], "media": [{"poster": "previews/art-hero.png", "kind": "scene animation", "caption": "agency-as-park · architectural and scenic interpretation", "motion": "previews/art-hero.gif"}], "image": "previews/art-hero.png"}, {"id": "e04", "title": "operating campus", "verb": "plan / assign / deliver", "loop": ["accept work", "reserve capacity", "produce", "review"], "sources": ["s01", "s19"], "type": "concepts", "implementation": "specified", "lead": "run a fictional agency through staffing, production, suppliers and commitments. investigate problems when they affect delivery.", "question": "does routine management sustain attention before an investigation begins?", "limit": "the portfolio, department and facility systems exceed the scope of the current scenarios.", "scope": "staffing, production and supplier decisions", "availability": "partial implementations", "revision": "design 0.1–0.16", "links": [], "media": [{"poster": "previews/reading-workshop.png", "kind": "illustrative animation", "caption": "workshop activity · 8-second illustration; episode state held", "motion": "previews/reading-workshop.gif"}], "image": "previews/reading-workshop.png"}, {"id": "e05", "title": "reconstruction park", "verb": "trace / compare / explain", "loop": ["conflict", "records", "explanation", "boundary"], "sources": ["s01", "s04"], "type": "concepts", "implementation": "specified", "lead": "arrange a reconstruction, compare records and test which explanations the evidence supports.", "question": "does comparing evidence create meaningful choices?", "limit": "a standalone reconstruction scenario is not available.", "scope": "record comparison and explanation building", "availability": "specification only", "revision": "design 0.1–0.16", "links": [], "media": [{"poster": "previews/e05.svg", "kind": "concept diagram", "caption": "reconstruction and record comparison · schematic"}], "image": "previews/e05.svg"}, {"id": "e06", "title": "operating game + historical anchors", "verb": "operate / compare / reflect", "loop": ["fictional run", "case comparison", "next chapter"], "sources": ["s01", "s04"], "type": "concepts", "implementation": "specified", "lead": "combine fictional management chapters with short comparisons against fixed historical records. deeper case reading is optional.", "question": "does the historical comparison improve understanding of the preceding run?", "limit": "the complete campaign and historical interactions are unbuilt.", "scope": "operating campus with reconstruction interludes", "availability": "specification only", "revision": "design 0.1–0.16", "links": [], "media": [{"poster": "previews/e06.svg", "kind": "concept diagram", "caption": "management chapters and historical comparisons · schematic"}], "image": "previews/e06.svg"}, {"id": "e07", "title": "28-quarter chronology campaign", "verb": "unlock / compare / advance", "loop": ["quarter", "records", "relationship", "next quarter"], "sources": ["s09"], "type": "concepts", "implementation": "specified", "lead": "a 28-quarter campaign with dated unlocks, relationship tests and progression after each required relationship is mapped.", "question": "does timeline progression support discovery or only delay access?", "limit": "the campaign runtime is unavailable. the prototype 2 runtime contains the shorter make/buy scenario.", "scope": "dated progression and relationship gates", "availability": "runtime unavailable", "revision": "campaign specification", "links": [], "media": [{"poster": "previews/e07.svg", "kind": "concept diagram", "caption": "28-quarter campaign structure · schematic"}], "image": "previews/e07.svg"}, {"id": "e08", "title": "prototype 2 · make or buy", "verb": "choose / run / revise", "loop": ["choose plan", "see tradeoff", "revise", "compare"], "sources": ["s07", "s08"], "image": "previews/prototype-2.png", "facts": {"opening cash": "$48,000", "time model": "short staged proof", "internal work": "12 of 16 shop hours", "internal cost": "$6,400 modeled; no debit", "supplier": "$12,000 reserved; posted cash unchanged", "other job": "8 hours; make queues 4", "payment conflict": "not on playable path", "main question": "capacity vs usable cash"}, "type": "playables", "implementation": "implemented", "lead": "choose between shared shop capacity and supplier cash. run each plan, inspect the tradeoff and revise. both plans can deliver.", "question": "can players understand and replay the capacity–cash tradeoff without guidance?", "limit": "a short staged scenario; no half-day production calendar.", "scope": "capacity and cash tradeoff", "availability": "alternate branch", "revision": "prototype 2 · dc8050b", "links": [{"label": "prototype source", "url": "https://github.com/jalulia/RCT-MM/tree/88daf3c1bb1f24f249689b8a8bf9eefa7f49a20a/prototype-v2"}], "media": [{"poster": "previews/prototype-2.png", "kind": "interface capture", "caption": "make/buy scenario · opening interface"}]}, {"id": "e09", "title": "ordinary-work-first practice", "verb": "allocate / produce / hand off", "loop": ["plan", "staff + bay", "half-day turns", "closeout"], "sources": ["s10", "s11"], "image": "previews/ordinary-work.png", "facts": {"opening cash": "$40,000", "time model": "up to 8 half-day intervals", "internal work": "4 fabrication + 2 pack units", "internal cost": "$4,000 materials", "supplier": "$12,000; clean receipt tuesday am", "other job": "3 units due tuesday am", "payment conflict": "ordinary only", "main question": "crew + bay + make/buy"}, "type": "playables", "implementation": "implemented", "lead": "schedule production through half-day turns, shared staffing and work-bay choices. the supplier payment succeeds.", "question": "do staffing and placement create useful choices without a payment conflict?", "limit": "eight half-day intervals; no returned-payment investigation in the default scenario.", "scope": "staff allocation, bay placement and make/buy choice", "availability": "alternate branch", "revision": "ordinary-1 · 88daf3c", "links": [{"label": "scenario source", "url": "https://github.com/jalulia/RCT-MM/tree/88daf3c1bb1f24f249689b8a8bf9eefa7f49a20a/ordinary-work"}], "media": [{"poster": "previews/ordinary-work.png", "kind": "interface capture", "caption": "ordinary production · opening interface"}]}, {"id": "e10", "title": "episode 01 · the handoff", "verb": "operate / inspect / respond", "loop": ["production", "payment conflict", "response", "closeout"], "sources": ["s05", "s06"], "image": "previews/episode-supplier-run.png", "facts": {"opening cash": "$40,000", "time model": "up to 12 half-day intervals", "internal work": "6 fabrication + 2 pack units", "internal cost": "$4,000 materials", "supplier": "$12,000; return or ordinary control", "other job": "3 units due tuesday pm", "payment conflict": "full route + ordinary control", "main question": "delivery decisions under a payment conflict"}, "type": "playables", "implementation": "implemented", "lead": "complete a production job while resolving a returned payment. request records, obtain approval, reissue payment or arrange substitute production.", "question": "does record inspection change an operating decision?", "limit": "fictional values and responses. historical comparison is disabled; participant comprehension and session length are unmeasured.", "scope": "production and payment conflict; ordinary control available", "availability": "main", "revision": "episode 01 · design 0.16", "links": [{"label": "play episode", "url": "https://jalulia.github.io/RCT-MM/Design/episode-01/"}], "media": [{"poster": "previews/episode-supplier-run.png", "kind": "gameplay capture", "caption": "returned payment → approval → handoff · condensed playthrough", "motion": "previews/episode-supplier-run.gif"}]}, {"id": "e11", "title": "standalone park builder", "verb": "place / compose / animate", "loop": ["object", "placement", "scene", "gif"], "sources": ["s14", "s13"], "image": "previews/park-builder.png", "type": "tools", "implementation": "implemented", "lead": "place, move and remove objects, people and looping events. compose a scene and export a gif.", "question": "which arrangements improve spatial readability and interaction?", "limit": "scene composition only; object placement has no financial or production effects.", "scope": "placement, animation and scene export", "availability": "main", "revision": "park builder · 4fbf10c", "links": [{"label": "open park builder", "url": "https://jalulia.github.io/RCT-MM/test/"}], "media": [{"poster": "previews/park-builder.png", "kind": "interface capture", "caption": "park builder · placement interface"}, {"poster": "previews/art-hero.png", "motion": "previews/art-hero.gif", "kind": "scene animation", "caption": "shared park objects · composed animation loop"}]}, {"id": "e12", "title": "design whiteboard", "verb": "sketch / connect / replay", "loop": ["objects + notes", "rules / beats", "replay", "discussion"], "sources": ["s12"], "image": "previews/board-views.png", "type": "tools", "implementation": "implemented", "lead": "edit shared records through systems, story and structure views. draw connections, replay scenario rules and save checkpoints.", "question": "can a group test relationships and assumptions while keeping rules distinct from notes?", "limit": "shared rooms require a configured supabase project. notes and drawn connections have no effect unless assigned a rule.", "scope": "scene-independent game design board", "availability": "main; room setup pending", "revision": "whiteboard · design 0.16", "links": [{"label": "open whiteboard", "url": "https://jalulia.github.io/RCT-MM/Design/whiteboard/?revision=0.16"}], "media": [{"poster": "previews/board-views.png", "kind": "interface sequence", "caption": "systems → story → structure · three views of shared records", "motion": "previews/board-views.gif"}]}, {"id": "e13", "title": "tabletop game", "verb": "mechanics undefined", "loop": [], "sources": ["s22"], "type": "concepts", "implementation": "outlined", "lead": "a tabletop alternative to the tycoon format, with monopoly as a reference for board-based play.", "question": "which shared activity and outcome should the tabletop format support?", "limit": "player count, actions, ownership rules, turn structure and victory conditions are undefined.", "scope": "tabletop format; mechanics open", "availability": "design outline", "revision": "tabletop concept", "links": [], "media": [{"poster": "previews/e13.svg", "kind": "concept diagram", "caption": "tabletop format · mechanics undefined · schematic"}], "image": "previews/e13.svg"}, {"id": "e14", "title": "bounded historical role", "verb": "act within known limits", "loop": ["dated access", "local choice", "fixed history"], "sources": ["s21"], "type": "agency", "implementation": "outlined", "lead": "play a role within a historical sequence. available information, authority and local actions are constrained by that role.", "question": "what could this role know, authorize and change at each point?", "limit": "permitted actions and their effects are undefined. no historical-role scenario is implemented.", "scope": "bounded actions within fixed history", "availability": "design outline", "revision": "agency outline", "links": [], "media": [{"poster": "previews/e14.svg", "kind": "concept diagram", "caption": "bounded agency within fixed history · schematic"}], "image": "previews/e14.svg"}, {"id": "e15", "title": "open counterfactual management", "verb": "change outcomes", "loop": ["fictional setup", "intervention", "new outcome"], "sources": ["s21"], "type": "agency", "implementation": "outlined", "lead": "manage a fictionalized situation in which interventions can produce different outcomes.", "question": "which outcomes should player decisions be able to change?", "limit": "the extent of control, available interventions and relationship to historical events are undefined.", "scope": "interventions with variable outcomes", "availability": "design outline", "revision": "agency outline", "links": [], "media": [{"poster": "previews/e15.svg", "kind": "concept diagram", "caption": "interventions with variable outcomes · schematic"}], "image": "previews/e15.svg"}], "relations": [{"from": "e06", "to": "e04", "type": "combines", "label": "management chapters"}, {"from": "e06", "to": "e05", "type": "combines", "label": "historical comparison"}, {"from": "e08", "to": "e04", "type": "tests", "label": "capacity and cash"}, {"from": "e09", "to": "e04", "type": "tests", "label": "ordinary production"}, {"from": "e10", "to": "e04", "type": "tests", "label": "production under payment conflict"}, {"from": "e11", "to": "e03", "type": "supports", "label": "spatial composition"}, {"from": "e12", "to": "e10", "type": "uses", "label": "episode rules for replay"}], "relationTypes": {"combines": "joins activities from two concepts.", "tests": "implements a bounded part of a concept.", "supports": "provides a design activity for a concept.", "uses": "loads rules or records from a scenario."}, "decisions": [{"id": "d01", "title": "purpose", "definition": "the intended effect of the game beyond completing a session.", "state": "open", "question": "what should the game help people understand, experience or do?"}, {"id": "d02", "title": "audience", "definition": "the people the game is designed for, including their knowledge and context of play.", "state": "open", "question": "who is playing, and what do they already know?"}, {"id": "d03", "title": "format", "definition": "the medium and session structure through which play happens.", "state": "open", "question": "which activities need a simulation, a reconstruction interface or a tabletop format?"}, {"id": "d04", "title": "player role", "definition": "the position from which the player receives information and takes action.", "state": "open", "question": "is the player an operator, an investigator or a participant in another defined role?"}, {"id": "d05", "title": "agency", "definition": "the information, permissions and outcomes the player can change.", "state": "open", "question": "which events remain fixed, and which respond to player decisions?"}, {"id": "d06", "title": "session outcome", "definition": "the conditions that end play and the result presented at closeout.", "state": "open", "question": "what constitutes completion, success or failure for the chosen concept?"}], "mechanisms": [{"id": "m01", "title": "what gets placed?", "alternatives": ["clients, offices and affiliated companies as possible attractions", "projects as work clusters; sites, clients and legal entities kept distinct"], "scope": "proposed taxonomy; only small scenarios implemented", "sources": ["s21", "s02"]}, {"id": "m02", "title": "billpay: kiosk or workbench?", "alternatives": ["a spatial kiosk or a separate mini-game", "a record and payment workbench; only physical handoffs use distance"], "scope": "workbench direction implemented in episode 01", "sources": ["s21", "s02", "s05"]}, {"id": "m03", "title": "one world, several views", "alternatives": ["interactive infographic showing money, information and control", "work / cash / information / control / people with retained selection"], "scope": "implemented with different scope in each playable", "sources": ["s21", "s04", "s08"]}, {"id": "m04", "title": "three desk arrangements", "alternatives": ["a 1990s desktop for records and discoveries", "world + inspector; compare two records; read with a return target"], "scope": "interface proposal with working record drawers and material studies", "sources": ["s03", "s05"]}, {"id": "m05", "title": "office-space collection", "alternatives": ["mckibbin, boerum, johnson, porter, colorado and hong kong as a pack", "site identity separate from occupancy, department, ownership and obligations"], "scope": "three office-derived buildings developed; full site economy unbuilt", "sources": ["s21", "s02"]}, {"id": "m06", "title": "small attractions and easter eggs", "alternatives": ["office photographs become landmarks and possible activities", "chrysler loop, fedora moonwalk, cat, cutaways, courtyard variants and voila route"], "scope": "scenic interactions; no economic or evidence rewards attached", "sources": ["s13"]}, {"id": "m07", "title": "sandbox extensions and mods", "alternatives": ["extension packs and reusable content", "stable object types, scenario settings and separate source records"], "scope": "data boundaries proposed; no general mod platform built", "sources": ["s21", "s12", "s01"]}], "sources": [{"id": "s01", "title": "initial design manual", "revision": "design 0.1", "url": "https://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/archive/versions/0.1/GDD-0.1.md", "excerpt": "sources/s01.html", "points": ["operating campus: fictional production and resource management.", "reconstruction park: compare records and build a supported explanation.", "combined concept: management chapters followed by historical comparisons."]}, {"id": "s02", "title": "initial object model", "revision": "design 0.1", "url": "https://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/archive/versions/0.1/GDD-0.1.md", "excerpt": "sources/s02.html", "points": ["a project coordinates deliverables, labor and supplier requirements.", "a site supplies space and facilities. occupancy connects it to an organization over time.", "a legal entity holds accounts, contracts, assets and obligations.", "a payment attempt has its own settlement state. a record documents a claim about that state."]}, {"id": "s03", "title": "three desk arrangements", "revision": "design 0.1", "url": "https://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/archive/versions/0.1/GDD-0.1.md", "excerpt": "sources/s03.html", "points": ["world + inspector: retain a selected object while showing its records.", "comparison: place related records side by side.", "reading: open a document with a return point to the prior task."]}, {"id": "s04", "title": "current game proposal", "revision": "design 0.16", "url": "https://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/GDD.md", "excerpt": "sources/s04.html", "points": ["the operating concept covers staffing, suppliers, delivery and cash commitments.", "the reconstruction concept covers conflicting records and supported explanations.", "historical comparison has separate access and evidence requirements."]}, {"id": "s05", "title": "episode 01 implementation", "revision": "main · af17388", "url": "https://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/episode-01/README.md", "excerpt": "sources/s05.html", "points": ["the scenario advances in half-day intervals.", "production, cash, records and permissions constrain the available responses.", "the returned-payment route and ordinary control are separate scenario settings."]}, {"id": "s06", "title": "episode 01 rules", "revision": "design 0.16", "url": "https://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/GDD.md", "excerpt": "sources/s06.html", "points": ["opening cash: $40,000.", "internal production: six fabrication units, two packing units and $4,000 materials.", "supplier commitment: $12,000.", "a three-unit display job is due tuesday afternoon. the run permits up to twelve half-day intervals."]}, {"id": "s07", "title": "prototype 2 runtime", "revision": "add/prototype-v2-playable · 88daf3c", "url": "https://github.com/jalulia/RCT-MM/blob/88daf3c1bb1f24f249689b8a8bf9eefa7f49a20a/prototype-v2/latest.js", "excerpt": "sources/s07.html", "points": ["opening cash: $48,000.", "internal plan: twelve of sixteen shop hours and $6,400 modeled cost.", "supplier plan: $12,000 reserved; posted cash remains unchanged.", "the competing eight-hour job queues four hours under the internal plan."]}, {"id": "s08", "title": "prototype 2 evaluation criteria", "revision": "branch build · design 0.12 / art 0.10", "url": "https://github.com/jalulia/RCT-MM/blob/88daf3c1bb1f24f249689b8a8bf9eefa7f49a20a/prototype-v2/QA.md", "excerpt": "sources/s08.html", "points": ["the core decision is shared capacity versus usable cash.", "plan comparison requires a visible consequence for the second job.", "the scenario tests whether the tradeoff can be understood and replayed without guidance."]}, {"id": "s09", "title": "earlier campaign integration note", "revision": "revision 1 · describes an earlier runtime", "url": "https://github.com/jalulia/RCT-MM/blob/88daf3c1bb1f24f249689b8a8bf9eefa7f49a20a/prototype-v2/VISUAL_INTEGRATION.md", "excerpt": "sources/s09.html", "points": ["the campaign spans twenty-eight quarters.", "dated records unlock as the timeline advances.", "relationship checks gate progression to the next quarter.", "the campaign runtime is unavailable."]}, {"id": "s10", "title": "ordinary-work-first practice", "revision": "ordinary-1 · branch 88daf3c", "url": "https://github.com/jalulia/RCT-MM/blob/88daf3c1bb1f24f249689b8a8bf9eefa7f49a20a/ordinary-work/README.md", "excerpt": "sources/s10.html", "points": ["two staff units are available per half-day.", "internal production requires four fabrication and two packing units, plus $4,000 materials.", "the $12,000 supplier route settles successfully.", "staff allocation and work-bay placement affect delivery."]}, {"id": "s11", "title": "ordinary practice checks", "revision": "recorded 17 september 2026; not a participant test", "url": "https://github.com/jalulia/RCT-MM/blob/88daf3c1bb1f24f249689b8a8bf9eefa7f49a20a/ordinary-work/VERIFY.md", "excerpt": "sources/s11.html", "points": ["model checks cover production, staffing, bay placement and ordinary payment.", "automated checks establish runtime behavior. participant comprehension and session length remain unmeasured."]}, {"id": "s12", "title": "whiteboard / cms boundary", "revision": "design 0.16", "url": "https://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/whiteboard/CMS.md", "excerpt": "sources/s12.html", "points": ["a record has one identity across systems, story and structure views.", "rules, narrative beats, objects and notes are distinct types.", "scenario effects are evaluated by the episode rules.", "local saves and shared rooms use separate persistence mechanisms."]}, {"id": "s13", "title": "park interaction studies", "revision": "checked in source against design 0.15", "url": "https://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/research/park-logic-review.md", "excerpt": "sources/s13.html", "points": ["a spatial object represents a site, facility, work cluster or landmark.", "physical handoffs can depend on distance.", "payment and information relationships need explicit states and permissions.", "scenic routes and small animations have no economic effects."]}, {"id": "s14", "title": "published tools and build inventory", "revision": "design 0.16 / art 0.10", "url": "https://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/README.md", "excerpt": "sources/s14.html", "points": ["the design reader presents the current specification.", "the episode is a production and payment scenario.", "the park builder composes scenes. the whiteboard edits and replays relationships.", "the sprite catalogue and preview library provide shared visual assets."]}, {"id": "s15", "title": "existing production sequence", "revision": "design 0.16 · operating-game proposal", "url": "https://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/GDD.md", "excerpt": "sources/s15.html", "points": ["p2: test the ordinary production loop without instruction.", "p3: compare operating and reconstruction structures.", "p4: evaluate the full fictional episode.", "purpose, audience and format remain separate design decisions."]}, {"id": "s16", "title": "early forensic explainer plan", "revision": "archived june 2026 precursor", "url": "https://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/archive/legacy-explainer/00_PLAN.md", "excerpt": "sources/s16.html", "points": ["the presentation organizes a case account into chapters.", "diagrams show relationships, timelines and flows.", "source records support the explanatory sequence."]}, {"id": "s17", "title": "specimen-world design brief", "revision": "brief says june 2026 · adjacent presentation work", "url": null, "excerpt": "sources/s17.html", "points": ["documents become movable paper, terminals and interactive specimens.", "a component bench isolates reusable controls and material treatments.", "the presentation has no production calendar or management economy."]}, {"id": "s18", "title": "retained design 0.3", "revision": "design 0.3 · retained copy", "url": null, "excerpt": "sources/s18.html", "points": ["design 0.3 retains the early operating and reconstruction alternatives.", "the retained copy has the same gameplay text as the archived 0.3 specification."]}, {"id": "s19", "title": "systems research proposals", "revision": "current research; larger economy proposed", "url": "https://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/research/systems.md", "excerpt": "sources/s19.html", "points": ["projects compete for staff, facilities and supplier capacity.", "contracts create commitments before cash movement.", "deliveries depend on both production and handoffs.", "information and authority restrict which corrective actions are available."]}, {"id": "s20", "title": "design revision history", "revision": "design 0.1–0.16", "url": "https://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/GDD.md", "excerpt": "sources/s20.html", "points": ["design 0.1–0.16 covers the operating concept, episode rules, art system and authoring tools.", "alternate-branch scenarios retain separate schedules and resource values.", "revision numbers identify artifacts; they do not define a single gameplay sequence."]}, {"id": "s21", "title": "spatial game model", "revision": "design outline", "url": null, "excerpt": "sources/s21.html", "points": ["agency-as-park: placeable work and sites, departments as staff, client and supplier visitors.", "bill-payment interface: a spatial kiosk or a record workbench.", "player agency: bounded actions within history or variable outcomes in a fictionalized scenario."]}, {"id": "s22", "title": "purpose, audience and format", "revision": "design outline", "url": null, "excerpt": "sources/s22.html", "points": ["purpose defines the intended effect. audience defines who the game serves.", "format defines the medium and session structure.", "tabletop play is an alternative with undefined mechanics. monopoly is a reference.", "player role, agency and session outcomes remain open."]}], "gaps": [{"title": "earlier simulation workspaces", "basis": "two earlier workspaces are referenced, but their implementations are unavailable."}, {"title": "28-quarter campaign", "basis": "a campaign specification exists; the matching runtime is unavailable."}, {"title": "tabletop rules", "basis": "player count, actions, ownership, turn structure and session outcomes remain undefined."}, {"title": "participant testing", "basis": "comprehension, session timing and replay interest remain unmeasured."}], "versions": [{"version": "0.1", "url": "https://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/archive/versions/0.1/GDD-0.1.md"}, {"version": "0.3", "url": "https://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/archive/versions/0.3/GDD-0.3.md"}, {"version": "0.4", "url": "https://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/archive/versions/0.4/GDD-0.4.md"}, {"version": "0.5", "url": "https://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/archive/versions/0.5/GDD-0.5.md"}, {"version": "0.6", "url": "https://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/archive/versions/0.6/GDD-0.6.md"}, {"version": "0.8", "url": "https://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/archive/versions/0.8/GDD.md"}, {"version": "0.9", "url": "https://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/archive/versions/0.9/GDD.md"}, {"version": "0.10", "url": "https://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/archive/versions/0.10/Design/GDD.md"}, {"version": "0.11", "url": "https://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/archive/versions/0.11/GDD.md"}, {"version": "0.12", "url": "https://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/archive/versions/0.12/GDD.md"}, {"version": "0.13", "url": "https://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/archive/versions/0.13/GDD.md"}, {"version": "0.14", "url": "https://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/archive/versions/0.14/GDD.md"}, {"version": "0.15", "url": "https://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/archive/versions/0.15/GDD.md"}], "branches": [{"name": "main", "revision": "af17388", "entries": ["e10", "e11", "e12"], "role": "episode, scene builder and whiteboard", "url": "https://github.com/jalulia/RCT-MM/tree/af17388216d8897600be507dc53b841070d4130c"}, {"name": "add/prototype-v2-playable", "revision": "88daf3c", "entries": ["e08", "e09"], "role": "make/buy and ordinary production scenarios", "url": "https://github.com/jalulia/RCT-MM/tree/88daf3c1bb1f24f249689b8a8bf9eefa7f49a20a"}]};
window.BASECAMP_MARKDOWN = "# mad money · basecamp · wip\n\n## record types\n\n- presentation studies: formats for reading, arranging and comparing case material.\n- game concepts: proposals for the player’s activity, objectives and progression.\n- playable scenarios: implemented situations with fixed rules, resources and outcomes.\n- design tools: applications for composing scenes, editing relationships and testing rules.\n- agency models: limits on what the player knows, controls and can change.\n\n## implementation stages\n\n- outlined: central activity identified; detailed rules remain open.\n- specified: rules or structure described; a complete runtime is not available.\n- implemented: an interactive artifact exists; its scope is stated separately.\n\n## design foundations\n\n### purpose · open\n\nthe intended effect of the game beyond completing a session.\n\nwhat should the game help people understand, experience or do?\n\n### audience · open\n\nthe people the game is designed for, including their knowledge and context of play.\n\nwho is playing, and what do they already know?\n\n### format · open\n\nthe medium and session structure through which play happens.\n\nwhich activities need a simulation, a reconstruction interface or a tabletop format?\n\n### player role · open\n\nthe position from which the player receives information and takes action.\n\nis the player an operator, an investigator or a participant in another defined role?\n\n### agency · open\n\nthe information, permissions and outcomes the player can change.\n\nwhich events remain fixed, and which respond to player decisions?\n\n### session outcome · open\n\nthe conditions that end play and the result presented at closeout.\n\nwhat constitutes completion, success or failure for the chosen concept?\n\n## e01 · forensic explainer\n\npresentation studies / implemented\n\na chaptered case account organized as diagrams, tables and records.\n\nactivity: read / trace / compare\n\nscope: chapter navigation and evidence diagrams\n\navailability: archived presentation\n\ntest question: can readers trace an explanation to its supporting records?\n\nunresolved scope: presentation only; no management economy or player-controlled outcome.\n\nrevision: presentation study · 2026-06\n\nsequence: chapter → diagram → source\n\nsources: s16\n\npreview: concept diagram · chaptered evidence presentation · schematic · previews/e01.svg\n\n## e02 · specimen world + component bench\n\npresentation studies / implemented\n\ncase material arranged as draggable paper, terminals and interactive specimens, with a separate component inspector.\n\nactivity: arrange / inspect / calculate\n\nscope: paper, terminal and component interactions\n\navailability: reference only\n\ntest question: which document interactions make dense information easier to examine?\n\nunresolved scope: visual interactions and calculations; no production schedule or management economy.\n\nrevision: material study · 2026-06\n\nsequence: artifact → interaction → inspection\n\nsources: s17\n\npreview: concept diagram · paper, terminal and component formats · schematic · previews/e02.svg\n\n## e03 · agency as a park\n\ngame concepts / outlined\n\nan agency represented as a park: departments, client and supplier visitors, sites and placeable work.\n\nactivity: place / manage / inspect\n\nscope: spatial management concept\n\navailability: design outline\n\ntest question: which objects require placement, and which belong in a record view?\n\nunresolved scope: the placement model must distinguish projects, sites and legal entities.\n\nrevision: concept · 2026-09\n\nsequence: place → watch → adjust\n\nsources: s21, s02\n\npreview: scene animation · agency-as-park · architectural and scenic interpretation · previews/art-hero.gif\n\n## e04 · operating campus\n\ngame concepts / specified\n\nrun a fictional agency through staffing, production, suppliers and commitments. investigate problems when they affect delivery.\n\nactivity: plan / assign / deliver\n\nscope: staffing, production and supplier decisions\n\navailability: partial implementations\n\ntest question: does routine management sustain attention before an investigation begins?\n\nunresolved scope: the portfolio, department and facility systems exceed the scope of the current scenarios.\n\nrevision: design 0.1–0.16\n\nsequence: accept work → reserve capacity → produce → review\n\nsources: s01, s19\n\npreview: illustrative animation · workshop activity · 8-second illustration; episode state held · previews/reading-workshop.gif\n\n## e05 · reconstruction park\n\ngame concepts / specified\n\narrange a reconstruction, compare records and test which explanations the evidence supports.\n\nactivity: trace / compare / explain\n\nscope: record comparison and explanation building\n\navailability: specification only\n\ntest question: does comparing evidence create meaningful choices?\n\nunresolved scope: a standalone reconstruction scenario is not available.\n\nrevision: design 0.1–0.16\n\nsequence: conflict → records → explanation → boundary\n\nsources: s01, s04\n\npreview: concept diagram · reconstruction and record comparison · schematic · previews/e05.svg\n\n## e06 · operating game + historical anchors\n\ngame concepts / specified\n\ncombine fictional management chapters with short comparisons against fixed historical records. deeper case reading is optional.\n\nactivity: operate / compare / reflect\n\nscope: operating campus with reconstruction interludes\n\navailability: specification only\n\ntest question: does the historical comparison improve understanding of the preceding run?\n\nunresolved scope: the complete campaign and historical interactions are unbuilt.\n\nrevision: design 0.1–0.16\n\nsequence: fictional run → case comparison → next chapter\n\nsources: s01, s04\n\npreview: concept diagram · management chapters and historical comparisons · schematic · previews/e06.svg\n\n## e07 · 28-quarter chronology campaign\n\ngame concepts / specified\n\na 28-quarter campaign with dated unlocks, relationship tests and progression after each required relationship is mapped.\n\nactivity: unlock / compare / advance\n\nscope: dated progression and relationship gates\n\navailability: runtime unavailable\n\ntest question: does timeline progression support discovery or only delay access?\n\nunresolved scope: the campaign runtime is unavailable. the prototype 2 runtime contains the shorter make/buy scenario.\n\nrevision: campaign specification\n\nsequence: quarter → records → relationship → next quarter\n\nsources: s09\n\npreview: concept diagram · 28-quarter campaign structure · schematic · previews/e07.svg\n\n## e08 · prototype 2 · make or buy\n\nplayable scenarios / implemented\n\nchoose between shared shop capacity and supplier cash. run each plan, inspect the tradeoff and revise. both plans can deliver.\n\nactivity: choose / run / revise\n\nscope: capacity and cash tradeoff\n\navailability: alternate branch\n\ntest question: can players understand and replay the capacity–cash tradeoff without guidance?\n\nunresolved scope: a short staged scenario; no half-day production calendar.\n\nrevision: prototype 2 · dc8050b\n\nsequence: choose plan → see tradeoff → revise → compare\n\n- opening cash: $48,000\n- time model: short staged proof\n- internal work: 12 of 16 shop hours\n- internal cost: $6,400 modeled; no debit\n- supplier: $12,000 reserved; posted cash unchanged\n- other job: 8 hours; make queues 4\n- payment conflict: not on playable path\n- main question: capacity vs usable cash\n\nsources: s07, s08\n\npreview: interface capture · make/buy scenario · opening interface · previews/prototype-2.png\n\n## e09 · ordinary-work-first practice\n\nplayable scenarios / implemented\n\nschedule production through half-day turns, shared staffing and work-bay choices. the supplier payment succeeds.\n\nactivity: allocate / produce / hand off\n\nscope: staff allocation, bay placement and make/buy choice\n\navailability: alternate branch\n\ntest question: do staffing and placement create useful choices without a payment conflict?\n\nunresolved scope: eight half-day intervals; no returned-payment investigation in the default scenario.\n\nrevision: ordinary-1 · 88daf3c\n\nsequence: plan → staff + bay → half-day turns → closeout\n\n- opening cash: $40,000\n- time model: up to 8 half-day intervals\n- internal work: 4 fabrication + 2 pack units\n- internal cost: $4,000 materials\n- supplier: $12,000; clean receipt tuesday am\n- other job: 3 units due tuesday am\n- payment conflict: ordinary only\n- main question: crew + bay + make/buy\n\nsources: s10, s11\n\npreview: interface capture · ordinary production · opening interface · previews/ordinary-work.png\n\n## e10 · episode 01 · the handoff\n\nplayable scenarios / implemented\n\ncomplete a production job while resolving a returned payment. request records, obtain approval, reissue payment or arrange substitute production.\n\nactivity: operate / inspect / respond\n\nscope: production and payment conflict; ordinary control available\n\navailability: main\n\ntest question: does record inspection change an operating decision?\n\nunresolved scope: fictional values and responses. historical comparison is disabled; participant comprehension and session length are unmeasured.\n\nrevision: episode 01 · design 0.16\n\nsequence: production → payment conflict → response → closeout\n\n- opening cash: $40,000\n- time model: up to 12 half-day intervals\n- internal work: 6 fabrication + 2 pack units\n- internal cost: $4,000 materials\n- supplier: $12,000; return or ordinary control\n- other job: 3 units due tuesday pm\n- payment conflict: full route + ordinary control\n- main question: delivery decisions under a payment conflict\n\nsources: s05, s06\n\npreview: gameplay capture · returned payment → approval → handoff · condensed playthrough · previews/episode-supplier-run.gif\n\n## e11 · standalone park builder\n\ndesign tools / implemented\n\nplace, move and remove objects, people and looping events. compose a scene and export a gif.\n\nactivity: place / compose / animate\n\nscope: placement, animation and scene export\n\navailability: main\n\ntest question: which arrangements improve spatial readability and interaction?\n\nunresolved scope: scene composition only; object placement has no financial or production effects.\n\nrevision: park builder · 4fbf10c\n\nsequence: object → placement → scene → gif\n\nsources: s14, s13\n\npreview: interface capture · park builder · placement interface · previews/park-builder.png\n\npreview: scene animation · shared park objects · composed animation loop · previews/art-hero.gif\n\n## e12 · design whiteboard\n\ndesign tools / implemented\n\nedit shared records through systems, story and structure views. draw connections, replay scenario rules and save checkpoints.\n\nactivity: sketch / connect / replay\n\nscope: scene-independent game design board\n\navailability: main; room setup pending\n\ntest question: can a group test relationships and assumptions while keeping rules distinct from notes?\n\nunresolved scope: shared rooms require a configured supabase project. notes and drawn connections have no effect unless assigned a rule.\n\nrevision: whiteboard · design 0.16\n\nsequence: objects + notes → rules / beats → replay → discussion\n\nsources: s12\n\npreview: interface sequence · systems → story → structure · three views of shared records · previews/board-views.gif\n\n## e13 · tabletop game\n\ngame concepts / outlined\n\na tabletop alternative to the tycoon format, with monopoly as a reference for board-based play.\n\nactivity: mechanics undefined\n\nscope: tabletop format; mechanics open\n\navailability: design outline\n\ntest question: which shared activity and outcome should the tabletop format support?\n\nunresolved scope: player count, actions, ownership rules, turn structure and victory conditions are undefined.\n\nrevision: tabletop concept\n\nsources: s22\n\npreview: concept diagram · tabletop format · mechanics undefined · schematic · previews/e13.svg\n\n## e14 · bounded historical role\n\nagency models / outlined\n\nplay a role within a historical sequence. available information, authority and local actions are constrained by that role.\n\nactivity: act within known limits\n\nscope: bounded actions within fixed history\n\navailability: design outline\n\ntest question: what could this role know, authorize and change at each point?\n\nunresolved scope: permitted actions and their effects are undefined. no historical-role scenario is implemented.\n\nrevision: agency outline\n\nsequence: dated access → local choice → fixed history\n\nsources: s21\n\npreview: concept diagram · bounded agency within fixed history · schematic · previews/e14.svg\n\n## e15 · open counterfactual management\n\nagency models / outlined\n\nmanage a fictionalized situation in which interventions can produce different outcomes.\n\nactivity: change outcomes\n\nscope: interventions with variable outcomes\n\navailability: design outline\n\ntest question: which outcomes should player decisions be able to change?\n\nunresolved scope: the extent of control, available interventions and relationship to historical events are undefined.\n\nrevision: agency outline\n\nsequence: fictional setup → intervention → new outcome\n\nsources: s21\n\npreview: concept diagram · interventions with variable outcomes · schematic · previews/e15.svg\n\n## relationships\n\n- operating game + historical anchors combines operating campus: management chapters\n- operating game + historical anchors combines reconstruction park: historical comparison\n- prototype 2 · make or buy tests operating campus: capacity and cash\n- ordinary-work-first practice tests operating campus: ordinary production\n- episode 01 · the handoff tests operating campus: production under payment conflict\n- standalone park builder supports agency as a park: spatial composition\n- design whiteboard uses episode 01 · the handoff: episode rules for replay\n\n## interaction studies\n\n### what gets placed?\n\n- clients, offices and affiliated companies as possible attractions\n- projects as work clusters; sites, clients and legal entities kept distinct\n\nproposed taxonomy; only small scenarios implemented\n\nsources: s21, s02\n\n### billpay: kiosk or workbench?\n\n- a spatial kiosk or a separate mini-game\n- a record and payment workbench; only physical handoffs use distance\n\nworkbench direction implemented in episode 01\n\nsources: s21, s02, s05\n\n### one world, several views\n\n- interactive infographic showing money, information and control\n- work / cash / information / control / people with retained selection\n\nimplemented with different scope in each playable\n\nsources: s21, s04, s08\n\n### three desk arrangements\n\n- a 1990s desktop for records and discoveries\n- world + inspector; compare two records; read with a return target\n\ninterface proposal with working record drawers and material studies\n\nsources: s03, s05\n\n### office-space collection\n\n- mckibbin, boerum, johnson, porter, colorado and hong kong as a pack\n- site identity separate from occupancy, department, ownership and obligations\n\nthree office-derived buildings developed; full site economy unbuilt\n\nsources: s21, s02\n\n### small attractions and easter eggs\n\n- office photographs become landmarks and possible activities\n- chrysler loop, fedora moonwalk, cat, cutaways, courtyard variants and voila route\n\nscenic interactions; no economic or evidence rewards attached\n\nsources: s13\n\n### sandbox extensions and mods\n\n- extension packs and reusable content\n- stable object types, scenario settings and separate source records\n\ndata boundaries proposed; no general mod platform built\n\nsources: s21, s12, s01\n\n## sources\n\n### s01 · initial design manual\n\ndesign 0.1\n\n- operating campus: fictional production and resource management.\n- reconstruction park: compare records and build a supported explanation.\n- combined concept: management chapters followed by historical comparisons.\n\nhttps://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/archive/versions/0.1/GDD-0.1.md\n\n### s02 · initial object model\n\ndesign 0.1\n\n- a project coordinates deliverables, labor and supplier requirements.\n- a site supplies space and facilities. occupancy connects it to an organization over time.\n- a legal entity holds accounts, contracts, assets and obligations.\n- a payment attempt has its own settlement state. a record documents a claim about that state.\n\nhttps://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/archive/versions/0.1/GDD-0.1.md\n\n### s03 · three desk arrangements\n\ndesign 0.1\n\n- world + inspector: retain a selected object while showing its records.\n- comparison: place related records side by side.\n- reading: open a document with a return point to the prior task.\n\nhttps://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/archive/versions/0.1/GDD-0.1.md\n\n### s04 · current game proposal\n\ndesign 0.16\n\n- the operating concept covers staffing, suppliers, delivery and cash commitments.\n- the reconstruction concept covers conflicting records and supported explanations.\n- historical comparison has separate access and evidence requirements.\n\nhttps://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/GDD.md\n\n### s05 · episode 01 implementation\n\nmain · af17388\n\n- the scenario advances in half-day intervals.\n- production, cash, records and permissions constrain the available responses.\n- the returned-payment route and ordinary control are separate scenario settings.\n\nhttps://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/episode-01/README.md\n\n### s06 · episode 01 rules\n\ndesign 0.16\n\n- opening cash: $40,000.\n- internal production: six fabrication units, two packing units and $4,000 materials.\n- supplier commitment: $12,000.\n- a three-unit display job is due tuesday afternoon. the run permits up to twelve half-day intervals.\n\nhttps://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/GDD.md\n\n### s07 · prototype 2 runtime\n\nadd/prototype-v2-playable · 88daf3c\n\n- opening cash: $48,000.\n- internal plan: twelve of sixteen shop hours and $6,400 modeled cost.\n- supplier plan: $12,000 reserved; posted cash remains unchanged.\n- the competing eight-hour job queues four hours under the internal plan.\n\nhttps://github.com/jalulia/RCT-MM/blob/88daf3c1bb1f24f249689b8a8bf9eefa7f49a20a/prototype-v2/latest.js\n\n### s08 · prototype 2 evaluation criteria\n\nbranch build · design 0.12 / art 0.10\n\n- the core decision is shared capacity versus usable cash.\n- plan comparison requires a visible consequence for the second job.\n- the scenario tests whether the tradeoff can be understood and replayed without guidance.\n\nhttps://github.com/jalulia/RCT-MM/blob/88daf3c1bb1f24f249689b8a8bf9eefa7f49a20a/prototype-v2/QA.md\n\n### s09 · earlier campaign integration note\n\nrevision 1 · describes an earlier runtime\n\n- the campaign spans twenty-eight quarters.\n- dated records unlock as the timeline advances.\n- relationship checks gate progression to the next quarter.\n- the campaign runtime is unavailable.\n\nhttps://github.com/jalulia/RCT-MM/blob/88daf3c1bb1f24f249689b8a8bf9eefa7f49a20a/prototype-v2/VISUAL_INTEGRATION.md\n\n### s10 · ordinary-work-first practice\n\nordinary-1 · branch 88daf3c\n\n- two staff units are available per half-day.\n- internal production requires four fabrication and two packing units, plus $4,000 materials.\n- the $12,000 supplier route settles successfully.\n- staff allocation and work-bay placement affect delivery.\n\nhttps://github.com/jalulia/RCT-MM/blob/88daf3c1bb1f24f249689b8a8bf9eefa7f49a20a/ordinary-work/README.md\n\n### s11 · ordinary practice checks\n\nrecorded 17 september 2026; not a participant test\n\n- model checks cover production, staffing, bay placement and ordinary payment.\n- automated checks establish runtime behavior. participant comprehension and session length remain unmeasured.\n\nhttps://github.com/jalulia/RCT-MM/blob/88daf3c1bb1f24f249689b8a8bf9eefa7f49a20a/ordinary-work/VERIFY.md\n\n### s12 · whiteboard / cms boundary\n\ndesign 0.16\n\n- a record has one identity across systems, story and structure views.\n- rules, narrative beats, objects and notes are distinct types.\n- scenario effects are evaluated by the episode rules.\n- local saves and shared rooms use separate persistence mechanisms.\n\nhttps://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/whiteboard/CMS.md\n\n### s13 · park interaction studies\n\nchecked in source against design 0.15\n\n- a spatial object represents a site, facility, work cluster or landmark.\n- physical handoffs can depend on distance.\n- payment and information relationships need explicit states and permissions.\n- scenic routes and small animations have no economic effects.\n\nhttps://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/research/park-logic-review.md\n\n### s14 · published tools and build inventory\n\ndesign 0.16 / art 0.10\n\n- the design reader presents the current specification.\n- the episode is a production and payment scenario.\n- the park builder composes scenes. the whiteboard edits and replays relationships.\n- the sprite catalogue and preview library provide shared visual assets.\n\nhttps://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/README.md\n\n### s15 · existing production sequence\n\ndesign 0.16 · operating-game proposal\n\n- p2: test the ordinary production loop without instruction.\n- p3: compare operating and reconstruction structures.\n- p4: evaluate the full fictional episode.\n- purpose, audience and format remain separate design decisions.\n\nhttps://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/GDD.md\n\n### s16 · early forensic explainer plan\n\narchived june 2026 precursor\n\n- the presentation organizes a case account into chapters.\n- diagrams show relationships, timelines and flows.\n- source records support the explanatory sequence.\n\nhttps://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/archive/legacy-explainer/00_PLAN.md\n\n### s17 · specimen-world design brief\n\nbrief says june 2026 · adjacent presentation work\n\n- documents become movable paper, terminals and interactive specimens.\n- a component bench isolates reusable controls and material treatments.\n- the presentation has no production calendar or management economy.\n\nsources/s17.html\n\n### s18 · retained design 0.3\n\ndesign 0.3 · retained copy\n\n- design 0.3 retains the early operating and reconstruction alternatives.\n- the retained copy has the same gameplay text as the archived 0.3 specification.\n\nsources/s18.html\n\n### s19 · systems research proposals\n\ncurrent research; larger economy proposed\n\n- projects compete for staff, facilities and supplier capacity.\n- contracts create commitments before cash movement.\n- deliveries depend on both production and handoffs.\n- information and authority restrict which corrective actions are available.\n\nhttps://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/research/systems.md\n\n### s20 · design revision history\n\ndesign 0.1–0.16\n\n- design 0.1–0.16 covers the operating concept, episode rules, art system and authoring tools.\n- alternate-branch scenarios retain separate schedules and resource values.\n- revision numbers identify artifacts; they do not define a single gameplay sequence.\n\nhttps://github.com/jalulia/RCT-MM/blob/af17388216d8897600be507dc53b841070d4130c/Design/GDD.md\n\n### s21 · spatial game model\n\ndesign outline\n\n- agency-as-park: placeable work and sites, departments as staff, client and supplier visitors.\n- bill-payment interface: a spatial kiosk or a record workbench.\n- player agency: bounded actions within history or variable outcomes in a fictionalized scenario.\n\nsources/s21.html\n\n### s22 · purpose, audience and format\n\ndesign outline\n\n- purpose defines the intended effect. audience defines who the game serves.\n- format defines the medium and session structure.\n- tabletop play is an alternative with undefined mechanics. monopoly is a reference.\n- player role, agency and session outcomes remain open.\n\nsources/s22.html\n\n## unresolved scope\n\n- earlier simulation workspaces: two earlier workspaces are referenced, but their implementations are unavailable.\n- 28-quarter campaign: a campaign specification exists; the matching runtime is unavailable.\n- tabletop rules: player count, actions, ownership, turn structure and session outcomes remain undefined.\n- participant testing: comprehension, session timing and replay interest remain unmeasured.\n";
